@section('content')<div class="admin-content"><h1>{{ $post->exists?'ویرایش مقاله':'مقاله جدید' }}</h1><form class="editor-card" method="POST" enctype="multipart/form-data" action="{{ $post->exists?route('admin.blog.update',$post):route('admin.blog.store') }}">@csrf @if($post->exists) @method('PUT') @endif<label>عنوان<input name="title" value="{{ $post->title }}" required></label><label>دسته‌بندی واقعی<input name="category" value="{{ $post->category?->name }}" list="blog-categories" placeholder="مثلاً آموزش، سئو، راهنمای خرید"><datalist id="blog-categories">@foreach($categories as $category)<option value="{{ $category->name }}">@endforeach</datalist></label><label>برچسب‌ها<input name="tags" value="{{ $post->tags?->pluck('name')->implode('، ') }}" placeholder="سئو، لاراول، فایل PDF"></label><label>تصویر شاخص واقعی<input type="file" name="featured_image" accept="image/jpeg,image/png,image/webp"><small>تصویر واقعی مقاله؛ حداکثر ۵MB. برای Open Graph نیز استفاده می‌شود.</small>@if($post->featured_image)<img class="current-featured" src="{{ asset(ltrim($post->featured_image,'/')) }}" alt="تصویر شاخص">@endif</label><label>خلاصه<textarea name="excerpt" rows="4">{{ $post->excerpt }}</textarea></label><label>عنوان سئو<input name="meta_title" value="{{ $post->meta_title }}" maxlength="255"></label><label>توضیحات متا<textarea name="meta_description" rows="3" maxlength="320">{{ $post->meta_description }}</textarea></label><label>محتوا<div class="blog-editor"><div class="blog-editor-toolbar"><button type="button" data-cmd="bold"><b>B</b></button><button type="button" data-cmd="italic"><i>I</i></button><button type="button" data-cmd="formatBlock" data-value="H2">H2</button><button type="button" data-cmd="formatBlock" data-value="H3">H3</button><button type="button" data-cmd="insertUnorderedList">فهرست</button><button type="button" data-cmd="blockquote">نقل‌قول</button><button type="button" data-cmd="createLink">پیوند</button></div><div class="blog-editor-area" contenteditable="true">{!! old('content',$post->content) !!}</div><textarea name="content" id="blogContent" hidden>{{ old('content',$post->content) }}</textarea></div></label><label class="check"><input type="checkbox" name="is_published" value="1" @checked($post->is_published)> انتشار</label><button>ذخیره مقاله</button></form></div>@endsection
@push('styles')<style>.admin-content{padding:24px}.editor-card{max-width:980px;background:#fff;border:1px solid #eaecf0;border-radius:16px;padding:20px;display:grid;gap:13px}.editor-card label{display:grid;gap:6px;font-size:11px;font-weight:800}.editor-card input,.editor-card textarea{font:inherit;border:1px solid #d0d5dd;border-radius:10px;padding:10px}.editor-card textarea{line-height:1.9}.editor-card small{font-size:9px;color:#98a2b3}.current-featured{width:min(520px,100%);max-height:250px;object-fit:cover;border-radius:12px}.editor-card .check{display:flex;align-items:center;gap:7px}.editor-card button{border:0;background:#111827;color:#fff;border-radius:10px;padding:11px;cursor:pointer}.blog-editor{border:1px solid #cfd5df;border-radius:12px;overflow:hidden}.blog-editor-toolbar{display:flex;flex-wrap:wrap;gap:4px;padding:8px;background:#f8fafc;border-bottom:1px solid #e4e7ec}.blog-editor-toolbar button{background:#fff;color:#344054;border:1px solid #e4e7ec;border-radius:7px;padding:7px 10px;font:inherit;font-size:9px}.blog-editor-area{min-height:380px;padding:16px;outline:0;line-height:2.2;font-size:12px}.blog-editor-area h2{font-size:21px}.blog-editor-area h3{font-size:17px}.blog-editor-area blockquote{padding:12px;border-right:3px solid #5b3cc4;background:#f7f5ff}.blog-editor-area table{width:100%;border-collapse:collapse}.blog-editor-area td{border:1px solid #ddd;padding:8px}</style>@endpush
@push('scripts')<script>document.addEventListener('DOMContentLoaded',()=>{const root=document.querySelector('.blog-editor');if(!root)return;const area=root.querySelector('.blog-editor-area'),out=document.getElementById('blogContent');const sync=()=>out.value=area.innerHTML;root.querySelectorAll('[data-cmd]').forEach(b=>b.addEventListener('click',()=>{area.focus();const c=b.dataset.cmd;if(c==='blockquote')document.execCommand('formatBlock',false,'BLOCKQUOTE');else if(c==='createLink'){const u=prompt('نشانی پیوند:');if(u)document.execCommand('createLink',false,u)}else document.execCommand(c,false,b.dataset.value||null);sync()}));area.addEventListener('input',sync);area.closest('form').addEventListener('submit',sync);sync()});</script>@endpush
